cd /luxon && cat > /tmp/verify_normalize.js <<'EOF'
const { Duration } = require("/luxon/src/luxon.js");

const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];
const values = [0, 1, 2, 3, 5, 7, 13, 25, 91, 100, -1, -2, -7, -13, -25, 1.5, -0.5];

let checked = 0, failures = [];

function msOf(obj, matrix) {
  let total = 0;
  for (const k of Object.keys(obj)) total += obj[k] * matrix.milliseconds[k];
  return total;
}

for (const acc of ["casual", "longterm"]) {
  const matrix = Duration.fromObject({ years: 1, conversionAccuracy: acc }).matrix;
  for (let i = 0; i < units.length; i++) {
    for (let j = 0; j < units.length; j++) {
      for (const a of values) {
        for (const b of values) {
          const input = {};
          input[units[i]] = a;
          input[units[j]] = b;
          const dur = Duration.fromObject(input, { conversionAccuracy: acc });
          const norm = dur.normalize().toObject();
          checked++;

          // 1. all outputs finite numbers
          for (const k of Object.keys(norm)) {
            if (typeof norm[k] !== "number" || !isFinite(norm[k])) {
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(norm)} non-finite ${k}`);
            }
          }

          // 2. total value preserved (in ms)
          const before = msOf(input, matrix);
          const after = msOf(norm, matrix);
          const tol = Math.max(1e-6, Math.abs(before) * 1e-9);
          if (Math.abs(before - after) > tol) {
            failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(norm)} value not preserved (${before} vs ${after})`);
          }

          // 3. canonical: each present unit magnitude < conversion to next larger present unit
          const present = units.filter(u => norm[u] !== undefined && norm[u] !== 0);
          for (let p = 0; p + 1 < present.length; p++) {
            const big = present[p], small = present[p + 1];
            const factor = matrix[big][small];
            if (Math.abs(norm[small]) >= Math.abs(factor) && norm[small] !== 0) {
              // allow when the big unit itself is the largest and remainder can't fold further
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(norm)} not canonical: ${small} (${norm[small]}) >= ${factor}`);
            }
          }
        }
      }
    }
  }
}

// 4. explicit expected values / cross-check with as() and shiftTo()
function expectEq(label, actual, expected) {
  const ok = typeof actual === "number" && isFinite(actual) && Math.abs(actual - expected) < 1e-9;
  console.log((ok ? "PASS" : "FAIL") + ` ${label}: ${actual} (expected ${expected})`);
  if (!ok) failures.push(label + ` got ${actual} expected ${expected}`);
}

