const { Duration } = require("/luxon/src/luxon.js");

const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];
const values = [0, 1, 2, 3, 5, 7, 13, 25, 91, 100, -1, -2, -7, -13, -25, 1.5, -0.5];

let checked = 0;
const failures = [];
const approx = (a, b) => Math.abs(a - b) <= Math.max(1e-6, Math.abs(b) * 1e-9);

for (const acc of ["casual", "longterm"]) {
  const matrix = Duration.fromObject({ years: 1, conversionAccuracy: acc }).matrix;
  for (let i = 0; i < units.length; i++) {
    for (let j = 0; j < units.length; j++) {
      for (const a of values) {
        for (const b of values) {
          const input = {};
          input[units[i]] = a;
          input[units[j]] = b;
          const dur = Duration.fromObject(input, { conversionAccuracy: acc });
          const norm = dur.normalize();
          const out = norm.toObject();
          checked++;

          // 1. every output is a finite number
          for (const k of Object.keys(out)) {
            if (typeof out[k] !== "number" || !isFinite(out[k])) {
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(out)}: non-finite ${k}`);
            }
          }

          // 2. normalize() is consistent with as()/shiftTo() for every unit
          for (const u of units) {
            const fromNorm = norm.as(u);
            const fromOrig = dur.as(u);
            if (!approx(fromNorm, fromOrig)) {
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(out)}: as('${u}') ${fromNorm} != original ${fromOrig}`);
            }
          }

          // 3. canonical: each present unit is smaller than one of the next larger present unit
          const present = units.filter(u => out[u] !== undefined && out[u] !== 0);
          for (let p = 0; p + 1 < present.length; p++) {
            const big = present[p], small = present[p + 1];
            const factor = matrix[big][small];
            if (typeof factor !== "number") {
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(out)}: no matrix factor ${big}->${small}`);
            } else if (Math.abs(out[small]) >= Math.abs(factor)) {
              failures.push(`[${acc}] ${JSON.stringify(input)} -> ${JSON.stringify(out)}: not canonical, ${small}=${out[small]} vs ${factor}`);
            }
          }

          // 4. idempotent
          const again = norm.normalize().toObject();
          if (JSON.stringify(again) !== JSON.stringify(out)) {
            failures.push(`[${acc}] ${JSON.stringify(input)}: not idempotent ${JSON.stringify(out)} -> ${JSON.stringify(again)}`);
          }

          // 5. normalize() agrees with shiftTo() over the same units
          const keys = Object.keys(input);
          const shifted = dur.shiftTo(...keys).toObject();
          for (const k of new Set([...keys, ...Object.keys(out)])) {
            const x = out[k] === undefined ? 0 : out[k];
            const y = shifted[k] === undefined ? 0 : shifted[k];
            if (!approx(x, y)) {
              failures.push(`[${acc}] ${JSON.stringify(input)}: normalize ${JSON.stringify(out)} != shiftTo(${keys}) ${JSON.stringify(shifted)}`);
              break;
            }
          }
        }
      }
    }
  }
}

// explicit expected values
function expectEq(label, actual, expected) {
  const ok = typeof actual === "number" && isFinite(actual) && approx(actual, expected);
  console.log((ok ? "PASS" : "FAIL") + ` ${label}: ${actual} (expected ${expected})`);
  if (!ok) failures.push(label + ` got ${actual} expected ${expected}`);
}

