import { DateTime } from "/luxon/src/luxon.js";

let failures = 0;
function check(label, actual, expected) {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${label}: ${JSON.stringify(actual)}${ok ? "" : " (expected " + JSON.stringify(expected) + ")"}`);
}

function padYear(y, n) {
  const sign = y < 0 ? "-" : "";
  return sign + String(Math.abs(y)).padStart(n, "0");
}

const years = [-10000, -1000, -100, -10, -1, 0, 1, 10, 100, 1000, 10000];

console.log("=== toISODate / toISO / toISOWeekDate / toFormat padding ===");
for (const y of years) {
  const dt = DateTime.fromObject({ year: y, month: 1, day: 1, zone: "utc" });

  // ISO 8601: expanded representation uses a leading + for years > 9999
  const isoYear = y > 9999 ? "+" + y : padYear(y, 4);
  check(`year ${y} toISODate`, dt.toISODate(), `${isoYear}-01-01`);
  check(`year ${y} toISO prefix`, dt.toISO().slice(0, dt.toISODate().length), dt.toISODate());
  check(`year ${y} toFormat('yyyy')`, dt.toFormat("yyyy"), isoYear);
  check(`year ${y} toFormat('yyyyyy')`, dt.toFormat("yyyyyy"), padYear(y, 6));

  // week date: the year shown is the ISO week-year, padded the same way
  const wkYear = dt.weekYear;
  const wkYearStr = wkYear > 9999 ? "+" + wkYear : padYear(wkYear, 4);
  check(
    `year ${y} toISOWeekDate`,
    dt.toISOWeekDate(),
    `${wkYearStr}-W${String(dt.weekNumber).padStart(2, "0")}-${dt.weekday}`
  );
}

console.log("\n=== exact bug-report cases ===");
check(
  "fromObject({year:-1}).toISODate()",
  DateTime.fromObject({ year: -1, month: 1, day: 1, zone: "utc" }).toISODate(),
  "-0001-01-01"
);
check(
  "fromObject({year:-10}).toISODate()",
  DateTime.fromObject({ year: -10, month: 1, day: 1, zone: "utc" }).toISODate(),
  "-0010-01-01"
);

console.log("\n=== round-trip through DateTime.fromISO (parser supports 4-digit years) ===");
for (const y of [0, 1, 10, 100, 1000, 9999]) {
  const dt = DateTime.fromObject({ year: y, month: 1, day: 1, zone: "utc" });
  const iso = dt.toISODate();
  const back = DateTime.fromISO(iso, { zone: "utc" });
  check(`round-trip ${iso}`, back.isValid ? back.toISODate() : "invalid", iso);
  check(`round-trip ${iso} year`, back.year, y);
}

console.log("\n=== round-trip for expanded years (informational) ===");
for (const y of [-10000, -1000, -100, -10, -1, 10000]) {
  const dt = DateTime.fromObject({ year: y, month: 1, day: 1, zone: "utc" });
  const iso = dt.toISODate();
  const back = DateTime.fromISO(iso, { zone: "utc" });
  console.log(`  ${iso} -> fromISO valid=${back.isValid}${back.isValid ? " year=" + back.year : ""}`);
}

console.log(`\n${failures === 0 ? "ALL CHECKS PASSED" : failures + " CHECK(S) FAILED"}`);
process.exit(failures === 0 ? 0 : 1);

